class Solution {
public:
  ListNode *reverseKGroup(ListNode *head, int k) {
    if (head == NULL) return head;
    ListNode *tail = head;
    while (k--) {
      if (tail == NULL) return head;
      tail = tail->next;
    }
    ListNode *cur = head, *pre = NULL, *next = NULL;
    while (cur != tail) //注意： reverse[head, tail)
    {
      next = cur->next;
      cur->next = pre;
      pre = cur;
      cur = next;
    }
    head->next = reverseKGroup(tail, k);
    return pre;
  }
};
